class Solution:
    def minSwaps(self, nums: List[int]) -> int:
        n = len(nums)
        swaps = 0
        changed = True
        while changed:
            changed = False
            for i in range(n):
                if nums[i] == 0:
                    for j in range(i + 1, n):
                        if nums[j] != 0:
                            nums[i], nums[j] = nums[j], nums[i]
                            swaps += 1
                            changed = True
                            break
        return swaps

