                if (nums[i] == 0) {
                    for (int j = i + 1; j < n; j++) {
                        if (nums[j] != 0) {
                            int t = nums[i]; nums[i] = nums[j]; nums[j] = t;
                            swaps++;
                            changed = true;
                            break;
                        }
                    }
                }
            }
        }
        return swaps;
    }
}

