var minSwaps = function(nums) {
    const n = nums.length;
    let swaps = 0, changed = true;
    while (changed) {
        changed = false;
        for (let i = 0; i < n; i++) {
            if (nums[i] === 0) {
                for (let j = i + 1; j < n; j++) {
                    if (nums[j] !== 0) {
                        [nums[i], nums[j]] = [nums[j], nums[i]];
                        swaps++;
                        changed = true;
                        break;
                    }
                }
            }
        }
    }
    return swaps;
};

